function Picker({ value, onChange, options, label }: {
    value: any;
    onChange: (s: string) => void;
    options: {
        value: string;
        label: string;
    }[];
    label?: string;
}) { return <Select value={String(value || '_none')} onValueChange={v => onChange(v === '_none' ? '' : v)}><SelectTrigger aria-label={label || 'Selecionar'} className="w-full"><SelectValue placeholder="Selecionar"/></SelectTrigger><SelectContent><SelectItem value="_none">Selecionar</SelectItem>{options.filter(x => x.value).map(x => <SelectItem value={x.value} key={x.value}>{x.label}</SelectItem>)}</SelectContent></Select>; }
const opts = (a: string[]) => a.map(x => ({ value: x, label: x }));
function Tag({ children }: any) { const t = String(children || ''); return <span className={'pill ' + (/Aprov|Conclu|Pago|Ativo|Dispon|escola/i.test(t) ? 'green' : /esper|rever|aprovar|Falta|Atras|Repor/i.test(t) ? 'orange' : /Online|Rascunho/i.test(t) ? 'purple' : '')}>{children || '—'}</span>; }
function Avatar({ name }: any) { return <span className="avatar">{String(name || '?').split(' ').slice(0, 2).map(s => s[0]).join('')}</span>; }
function Panel({ title, subtitle, action, children, className = '' }: any) { return <section className={'panel ' + className}><div className="panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Empty({ text = 'Ainda não existem registos.', action }: any) { return <div className="empty"><FileText size={28}/><h3>{text}</h3>{action}</div>; }
function download(name: string, text: string, type = 'text/plain') { const url = URL.createObjectURL(new Blob([text], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
