            if(sequence!==loadSequence.current)return;
            if(res.status===401&&new URLSearchParams(location.search).get('demo')==='1'){const samples=sampleRecords();setDemoMode(true);setShowExamples(true);setAuth(false);setOwner(false);setView(v);setRecords(samples.filter(r=>visible(r,{role:v,user:{userId:'preview'},therapist:'t1'},samples)));return;}
